    so far ends with a comma, or the next non-blank line starts with one.
    Yields (line_number, statement_text).
    """
    statements = []
    current = []
    start_line = None
    depth = 0
    line = 1
    i = 0
    n = len(text)

    def flush():
        stmt = "".join(current).strip()
        if stmt:
            statements.append((start_line, stmt))
        current.clear()

    while i < n:
        ch = text[i]
        if ch == "'":
            end = text.find("'", i + 1)
            nl = text.find("\n", i + 1)
            if end == -1 or (nl != -1 and nl < end):
                raise DslError("line %d: unterminated string literal" % line)
            if start_line is None:
                start_line = line
            current.append(text[i:end + 1])
            i = end + 1
            continue
        if ch == "#":
            nl = text.find("\n", i)
            i = n if nl == -1 else nl
            continue
        if ch == "\r":
            i += 1
            continue
        if ch == "\n":
            line += 1
            i += 1
