            if not so_far:
                continue
            if depth > 0 or so_far.endswith(","):
                current.append(" ")
                continue
            if _next_significant_char(text, i) == ",":
                current.append(" ")
                continue
            flush()
            start_line = None
            depth = 0
            continue
        if ch in "([":
            depth += 1
        elif ch in ")]":
            depth -= 1
        if start_line is None and not ch.isspace():
            start_line = line
        current.append(ch)
        i += 1
    flush()
